from typing import Any, TypeVar, Callable
from functools import wraps

T = TypeVar('T')

def check_non_negative(value: int | float, param_name: str = 'value') -> None:
    """EGRR_PATTERN: Validate non-negative number."""
    if value < 0:
        raise ValueError(f'{param_name} must be non-negative, got {value}')

def check_positive(value: int | float, param_name: str = 'value') -> None:
    """EGRR_PATTERN: Validate positive number."""
    if value <= 0:
        raise ValueError(f'{param_name} must be positive, got {value}')

def check_in_range(value: int | float, min_val: int | float, max_val: int | float, 
                   param_name: str = 'value') -> None:
    """EGRR_PATTERN: Validate value is within range."""
    if not min_val <= value <= max_val:
        raise ValueError(f'{param_name} must be between {min_val} and {max_val}, got {value}')

def check_not_empty(value: Any, param_name: str = 'value') -> None:
    """EGRR_PATTERN: Validate value is not empty/None."""
    if value is None:
        raise ValueError(f'{param_name} cannot be None')
    if isinstance(value, (str, list, dict, set)) and len(value) == 0:
        raise ValueError(f'{param_name} cannot be empty')

def validate_type(value: Any, expected_type: type | tuple, param_name: str = 'value') -> None:
    """EGRR_PATTERN: Validate value type."""
    if not isinstance(value, expected_type):
        raise TypeError(f'{param_name} must be {expected_type.__name__}, got {type(value).__name__}')

def validate_params(**validators: Callable):
    """EGRR_PATTERN: Decorator for parameter validation."""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get function parameter names
            import inspect
            sig = inspect.signature(func)
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()

            for param_name, validator in validators.items():
                if param_name in bound.arguments:
                    validator(bound.arguments[param_name], param_name)

            return func(*args, **kwargs)
        return wrapper
    return decorator
